   260→  const handleSplashComplete = () => {
   261→    setShowSplash(false);
   262→    sessionStorage.setItem("splash_shown", "true");
   263→  };
   264→
   265→  const handleOnboardingComplete = () => {
   266→    setShowOnboarding(false);
   267→    const verified = localStorage.getItem("invitation_verified");
   268→    if (verified !== "true") {
   269→      setNeedsInvitation(true);
   270→    }
   271→  };
   272→
   273→  const handleInvitationVerified = () => {
   274→    setNeedsInvitation(false);
   275→    const tutorialDone = localStorage.getItem("we_iku_tutorial_done");
   276→    if (!tutorialDone) {
   277→      setShowTutorial(true);
   278→    }
   279→  };
   280→
   281→  const handleTutorialComplete = () => {
   282→    setShowTutorial(false);
   283→  };
   284→
   285→  if (isAdminPage) {
   286→    return (
   287→      <QueryClientProvider client={queryClient}>
   288→        <TooltipProvider>
   289→          <ThemeInitializer />
   290→          <AdminStats />
   291→          <Toaster />
   292→        </TooltipProvider>
   293→      </QueryClientProvider>
   294→    );
   295→  }
   296→
   297→  if (isAdminDashboard) {
