   299→      <QueryClientProvider client={queryClient}>
   300→        <TooltipProvider>
   301→          <ThemeInitializer />
   302→          <AdminDashboard />
   303→          <Toaster />
   304→        </TooltipProvider>
   305→      </QueryClientProvider>
   306→    );
   307→  }
   308→
   309→  if (isTipsPage || isLegalPage) {
   310→    return (
   311→      <QueryClientProvider client={queryClient}>
   312→        <TooltipProvider>
   313→          <ThemeInitializer />
   314→          <Router />
   315→          <Toaster />
   316→        </TooltipProvider>
   317→      </QueryClientProvider>
   318→    );
   319→  }
   320→
   321→  return (
   322→    <QueryClientProvider client={queryClient}>
   323→      <TooltipProvider>
   324→        <ThemeInitializer />
   325→        <AnimatePresence>
   326→          {showSplash && <SplashScreen onComplete={handleSplashComplete} />}
   327→        </AnimatePresence>
   328→        {showOnboarding ? (
   329→          <Onboarding onComplete={handleOnboardingComplete} />
   330→        ) : needsInvitation ? (
