        className="ml-2 flex items-center gap-0.5 rounded-full bg-white/20 px-2 py-0.5 active:scale-95 transition-transform"
        data-testid="button-demo-exit"
      >
        <X className="w-3 h-3" />
        終了
      </button>
    </div>
  );
}

